# -*- coding: utf-8 -*-
# 2026 케이스북 퀴즈 국문 (12·13장)
C = []
def c(n, q, a, e, arts, ox=None, ch=None, cEn=None):
    d = {'n': n, 'q': q, 'a': a, 'e': e, 'arts': arts}
    if ox is not None: d['ox'] = ox
    if ch: d['c'] = ch
    if cEn: d['cEn'] = cEn
    C.append(d)

c('12.99.1', 'B4에게 테크니컬 파울이 주어지는 순간 A1이 트라이를 성공했다. A팀에 페널티 트라이를 주고 B4의 페널티 수행을 면제해야 하는가?', 1,
  '케이스북 12.99.1의 답: 아니다. 테크니컬 파울의 페널티는 어떤 상황에서도 수행한다.', [98], ox=1)
c('12.99.2', 'A1이 높이 든 볼을 B1이 닿지 못하자, B1이 A1의 눈앞에서 손을 흔들어 압박했다. A1은 별로 개의치 않는 듯했다. 레퍼리가 경기를 계속하게 한 것은 옳은가?', 1,
  '케이스북 12.99.2의 답: 옳지 않다. 눈앞에서 손을 흔드는 것은 비신사적이고 위험하므로 B1에게 테크니컬 파울을 주어야 한다.', [99], ox=1)
c('12.99.3', 'A팀이 3대2 속공을 하던 중 B1이 공격수 앞으로 들어와 A1과 우연히 접촉했고, 그 접촉을 이용해 넘어진 선수인 척 바닥에 쓰러져 경기를 멈추게 했다. 레퍼리가 경기를 멈추고 B1에게 테크니컬 파울을 준 것은 옳은가?', 0,
  '케이스북 12.99.3의 답: 옳다. B1이 경기를 중단시키려고 비신사적이고 위험한 방법을 썼다.', [99], ox=0)
c('12.99.4', 'B4가 전반 내내 A3 수비에 어려움을 겪다가, 후반에는 A3의 경기력을 조롱하며 집중력을 흐트러뜨리려 했다. 욕설을 쓰지 않았으니 레퍼리가 무시한 것은 옳은가?', 1,
  '케이스북 12.99.4의 답: 옳지 않다. 수비가 어렵다고 비신사적인 행동으로 메우려 한 것이므로 테크니컬 파울을 주어야 한다.', [99], ox=1)
c('12.99.5', 'A1이 스로인을 했고, 그 뒤 B1이 다가와 A1이 코트로 완전히 들어오는 것을 막았다. 레퍼리가 경기 지연으로 B1에게 테크니컬 파울을 준 것은 옳은가?', 0,
  '케이스북 12.99.5의 답: 옳다. 수비수는 스로인 직후 인바운더가 코트로 완전히 돌아오는 것을 막아서는 안 된다.', [99, 81], ox=0)
c('12.99.6', 'A1이 스로인을 마친 뒤 몇 초 있다가 코트로 들어오려 했고, B1이 완전히 들어오지 못하게 막았다. 레퍼리는 B1에게 테크니컬 파울을 주어야 하는가?', 0,
  '케이스북 12.99.6의 답: 그렇다. 시간은 문제가 아니다. 인바운더가 원할 때 코트에 들어오게 해야 하므로 B1에게 테크니컬 파울을 준다.', [99, 81], ox=0)
c('12.99.7', 'A1이 사이드라인에서 스로인한 뒤 B1 쪽으로 비스듬히 코트에 들어와 B1과 부딪히지 않고는 완전히 들어올 수 없게 되었다(B1은 1m 구역 밖에 있었다). 레퍼리가 경기 지연으로 B1에게 테크니컬 파울을 주어야 하는가?', 1,
  '케이스북 12.99.7의 답: 아니다. A1은 B1과 접촉하지 않고도 코트에 완전히 들어올 수 있다. A1이 일부러 B1에게 테크니컬 파울을 유도할 수는 없다.', [99, 81], ox=1)
c('12.99.8', 'B1이 페널티 박스에 있을 때 A2와 A3가 나오는 B1을 가두려 했다. A1이 트라이를 성공했고, B1이 게이트를 지키지 않고 불법하게 코트로 들어왔다. B1에게 테크니컬 파울을 주고 페널티를 추가로 수행하게 해야 하는가?', 0,
  '케이스북 12.99.8의 답: 그렇다. B1이 게이트를 무시해 이점을 얻었다.', [99, 106], ox=0)
c('12.99.9', 'A1이 1m 밖에서 사이드라인 가까이 있는 A2에게 인바운드했고, B1과 B2가 A2를 사이드라인 쪽으로 밀어붙였다. 코트에 들어온 A1이 A2와 접촉해 A2가 코트 밖으로 나가지 않게 막았다. 파울인가?', 0,
  '케이스북 12.99.9의 답: A1의 비신사적 행동이다. 동료가 코트 밖으로 나가지 않게 도와줄 수 없으므로 A1에게 테크니컬 파울을 주되 A팀은 볼 소유권을 유지한다.', [99, 97],
  ch=['A1에게 테크니컬 파울, A팀은 볼 소유 유지', 'A1에게 테크니컬 파울, 볼은 B팀', '파울 없음'], cEn=['Technical foul on A1, Team A keeps possession', 'Technical foul on A1, ball to Team B', 'No foul'])
c('12.99.10', 'B1이 A1의 적법한 충돌을 받아 한 바퀴로 균형을 잃었다. 이미 B1에게 적법한 충돌을 하려던 A2가 B1이 균형을 잃은 상태에서 그 충돌을 피하지 못해 B1이 넘어졌다. 레퍼리가 A2에게 테크니컬 파울을 준 것은 옳은가?', 0,
  '케이스북 12.99.10의 답: 옳다. 피할 수 없는 충돌이었더라도 위험한 플레이이므로 A2에게 책임이 있다. 테크니컬 파울을 주고 A팀은 볼을 계속 갖는다.', [99, 84], ox=0)
c('12.100.1', 'A코치가 경기력이 좋지 않은 자기 팀 선수들에게 모욕적인 말(욕설)을 했다. 말이 심판이나 상대 선수에게 향한 것이 아니므로 레퍼리가 넘어갔다. 옳은가?', 1,
  '케이스북 12.100.1의 답: 옳지 않다. 코트의 예의는 항상 지켜져야 하므로 코치에게 테크니컬 파울을 주어야 한다.', [100], ox=1)
c('12.100.2', '경기 중 B코치가 코트 위 선수들에게 지시하려고 팀 벤치 구역을 여러 번 벗어나 테이블 오피셜 업무를 방해했다. 레퍼리가 경고한 뒤 테크니컬 파울을 준 것은 옳은가?', 0,
  '케이스북 12.100.2의 답: 옳다.', [100], ox=0)
c('12.100.3', 'A2와 B3가 싸우기 시작했다. A팀 코치가 질서를 되찾는 것을 돕겠다고 팀 벤치 구역을 떠났다. 벤치를 떠난 것에 대해 테크니컬 파울을 주어야 하는가?', 1,
  '케이스북 12.100.3의 답: 아니다. 상식적으로 판단한다. 벤치 관계자가 싸움을 말리는 데 도움을 줬다면 제재하지 않는다.', [100], ox=1)
c('12.100.4', 'B팀 코트 위 선수 가운데 코치가 지정한 선발 4명이 아닌 선수가 있는 것이 드러났다. 경기 시작 전이라면 어떻게 하는가?', 0,
  '케이스북 12.100.4 a)의 답: 잘못 들어온 선수는 즉시 코트에서 나가고 코치가 지정한 선발 라인업이 들어온다. 테크니컬 파울은 주지 않는다. 경기가 시작된 뒤라면 코치에게 테크니컬 파울을 준다.',
  [100, 36], ch=['선수를 즉시 교체하고 테크니컬 파울은 주지 않는다', '코치에게 테크니컬 파울을 준다', '경기를 몰수한다'],
  cEn=['Replace the player immediately with no technical foul', 'Charge the coach a technical foul', 'Forfeit the game'])
c('12.100.5', 'B1이 일반 파울을 받고 페널티를 수행하기 시작했다. 벤치 관계자가 페널티 박스에 있는 B1에게 물을 가져다주었다. 이때 제재는?', 0,
  '케이스북 12.100.5의 답: 경기 중, 쿼터 사이 휴식, 추가 연장 피리어드 사이에는 벤치 테크니컬 파울이다. 다만 하프타임과 4쿼터~첫 연장 사이에는 바이얼레이션이 아니어서 B1이 벤치로 돌아갈 수 있다.', [100, 105],
  ch=['경기 중이면 벤치 테크니컬 파울, 하프타임에는 아니다', '언제나 벤치 테크니컬 파울', '언제나 파울 없음'],
  cEn=['Bench technical foul during live play, none at half time', 'Bench technical foul every time', 'No foul at any time'])
c('12.101.1', '대회 전 장비 점검에서 A팀의 모든 휠체어가 통과했다. 첫 경기에서 A1의 휠체어가 파손되어 수리되었고, 두 번째 경기에서 B팀이 그 휠체어의 적법성에 이의를 제기했다. 점검 결과 적법하다면 어떻게 처리하는가?', 0,
  '케이스북 12.101.1의 답: 휠체어를 다시 점검하고, 적법하다고 판정되면 점검을 요청한 B팀 코치에게 테크니컬 파울을 주어 B팀 코치가 고른 선수가 수행한다.', [101],
  ch=['다시 점검하고, 적법하면 요청한 B팀 코치에게 테크니컬 파울', '적법하면 아무 제재 없음', 'A1을 즉시 퇴장'],
  cEn=['Re-check the chair; if legal, charge a technical foul to the Team B coach who requested it', 'No sanction if legal', 'Disqualify A1 immediately'])
c('12.101.2', '경기 시작 10분 전 A코치가 B1의 휠체어에 이의를 제기했다. B1이 선발 라인업에 있는 경우 어떻게 처리하는가?', 0,
  '케이스북 12.101.2 A)의 답: 레퍼리는 이 요청을 받아들이지 않고, B1이 경기에 나와 코트에 들어온 뒤에 점검한다고 알린다. B1이 교체 선수라면 교체가 완료되어 경기에 들어올 때 점검한다.', [101, 36],
  ch=['요청을 받아들이지 않고, B1이 코트에 들어온 뒤 점검한다', '즉시 점검하게 한다'], cEn=['Decline the request; check the chair once B1 has entered the court', 'Check the chair immediately'])
c('12.102.1', 'A팀이 코트 위 등급분류 점수 초과로 테크니컬 파울을 받았다. 레퍼리가 A코치에게 페널티를 수행할 선수를 고르게 한 것은 옳은가?', 0,
  '케이스북 12.102.1의 답: 옳다. A코치가 코트 위 선수 중 수행할 선수를 고르고, 그다음 점수를 맞추기 위한 교체를 한다.', [102, 35], ox=0)
c('12.102.2', 'A1(3.0)과 A2(1.5)가 페널티를 수행 중이고 A3(3.0)가 차례를 기다리고 있었다. 최소 인원을 채우려고 A4(0.5)와 A5(3.0)가 뛰던 중 A4가 다쳐 더는 뛸 수 없게 되었다. 벤치에는 A6(3.0)과 A7(2.0)가 있다. A7로 교체해 경기를 계속할 수 있는가?', 0,
  '케이스북 12.102.2의 답: 점수 한도를 지키면서 A4를 대신할 선수가 없다. 이 경우 A팀은 그 시점에 경기를 몰수해야 한다.', [102, 111],
  ch=['몰수해야 한다', 'A7로 교체하고 계속한다', 'A6으로 교체하고 계속한다'], cEn=['Team A must forfeit', 'Substitute A7 and continue', 'Substitute A6 and continue'])
c('12.103.1', 'A1이 모든 수비수보다 충분히 앞서 있어 적법한 수비 접촉이 불가능한 상황이었다. B2가 비스듬히 쫓아와 볼 소유자의 뒷 캐스터 뒤쪽에 무모하게 접촉해 선수가 회전하거나 균형을 잃게 했다. 레퍼리가 B2에게 플래그런트 파울을 준 것은 옳은가?', 0,
  '케이스북 12.103.1의 답: 옳다. 비신사적인 플레이다. A팀에 페널티 트라이를 주고 B2는 페널티 두 개를 수행한다.', [103, 88], ox=0)
c('12.103.2', 'A1이 모든 수비수보다 앞서 트라이 라인을 넘으려는 순간, B2가 속도를 내 달려와 뒷축 근처에서 적법하게 수비할 각도가 없는데도 뒷 캐스터 뒤쪽에 비신사적으로 접촉해 A1을 바닥으로 넘어뜨렸다. 레퍼리가 B2에게 플래그런트 파울을 준 것은 옳은가?', 0,
  '케이스북 12.103.2의 답: 옳다. A팀에 페널티 트라이를 주고 B2는 페널티 두 개를 수행한다.', [103, 88], ox=0)
c('12.103.3', 'A1이 볼을 들고 코트를 올라가던 중 B1이 수비를 시도하다 놓쳤다. A1이 B1을 지나칠 때 B1이 볼을 건드리려는 시도 없이 A1의 팔을 잡았다. 선수 안전을 위협하며 경기를 멈춰 트라이를 막으려는 행위였지만, 다른 수비수들에게는 A1을 막을 기회가 있었다. 레퍼리는 이를 고의적 비신사 행위로 보았다. 플래그런트 파울과 함께 페널티 트라이를 주는 것이 옳은가?', 1,
  '케이스북 12.103.3의 답: 판정 자체는 플래그런트 파울이 맞지만, 다른 수비수들이 A1을 막을 기회가 있었으므로 페널티 트라이는 주지 않는다. B1은 트라이 릴리즈 30초 페널티 세 개를 수행한다.', [103, 88], ox=1)
c('12.103.4', 'A1이 B1과 적법하게 충돌해 A1이 한 바퀴로 잠시 균형을 잃었다. 그 상태에서 1m 떨어져 있던 B2가 무모하게 A1을 쳐서 넘어뜨렸다. 레퍼리가 B2에게 플래그런트 파울을 선언한 것은 옳은가?', 0,
  '케이스북 12.103.4의 답: 옳다. 무모하고 비신사적인 플레이다.', [103], ox=0)
c('12.103.5', '같은 경기에서 B2가 두 번째 플래그런트 파울을 범했다. 레퍼리가 플래그런트 파울을 신호한 뒤 디스퀄리파잉 파울을 신호하고, 교체 선수에게 그 페널티를 수행하게 했다. 옳은가?', 1,
  '케이스북 12.103.5의 답: 옳지 않다. 플래그런트 파울의 제재는 볼 소유권 상실이나 페널티 트라이가 아닌 한 트라이 릴리즈 30초 페널티 세 개다. 페널티 타임키퍼는 페널티 기록지에 퇴장 선수 B2의 플래그런트 파울을 기록하고, B2는 경기장을 떠난다. 코치는 적법한 라인업이 되게 교체할 수 있고, 페널티(플래그런트 파울의 제재)는 규정대로 코치가 고른 같은 팀 선수가 수행한다.', [103, 104], ox=1)
c('12.103.6', 'A1이 트라이 라인을 공격하고 B1이 먼 쪽 포스트 근처에서 A1보다 앞서 있었다. B1이 볼을 쳐내려 트라이 라인에서 A1을 공격했지만 접촉이 늦어 A1의 축 뒤쪽에 닿아 A1이 넘어졌다. 레퍼리가 B1에게 플래그런트 파울을 준 것은 옳은가?', 1,
  '케이스북 12.103.6의 답: 옳지 않다. B1은 이미 적법한 수비 자리를 잡았고 휠체어를 향한 정당한 시도였지만 늦게 도착한 것이다. 스피닝 파울을 주고 A팀에 페널티 트라이를 준다.', [103, 96, 88], ox=1)
c('12.103.7', 'A1이 포스트 쪽으로 비스듬히 트라이 라인을 공격하고, B1이 평행하게 옆에서 달리다 A1이 먼저 도착할 것을 알고 A1을 포스트 쪽으로 밀어 득점을 막으려 했다. 축에서의 접촉으로 A1이 포스트로 넘어졌다. 레퍼리가 B1에게 플래그런트 파울을 준 것은 옳은가?', 1,
  '케이스북 12.103.7의 답: 옳지 않다. 축에서의 접촉은 트라이 라인에서의 정당한 수비 시도다. 볼 소유권이 넘어가고 B팀이 코너에서 볼을 갖는다.', [103, 94], ox=1)
c('12.103.8', 'A1이 키 위쪽에서 트라이 라인을 공격하고, B2가 A1을 따라잡아 살짝 앞선 뒤 각도가 좋다고 판단해 몸을 돌려 A1을 쳤다. 접촉은 A1 뒷축의 중간(범퍼의 약 50%가 축 뒤, 50%가 축 앞)이었고 A1이 볼을 가진 채 앞으로 넘어졌다. 이 접촉은 무엇인가?', 1,
  '케이스북 12.103.8의 답: 플래그런트 파울이 아니다. 축 선상에서의 접촉으로 볼을 가진 선수가 바닥에 닿게 한 것은 트라이 라인에서의 정당한 수비다. A1에게 피지컬 어드밴티지 바이얼레이션을 주고 B팀이 사이드라인에서 볼을 갖는다.', [103, 78],
  ch=['플래그런트 파울', '피지컬 어드밴티지 바이얼레이션 — B팀 사이드라인 볼'], cEn=['Flagrant foul', 'Physical advantage on A1 - ball to Team B on the sideline'])
c('12.104.1', 'A1이 B1을 주먹으로 쳤다. 레퍼리가 A1에게 디스퀄리파잉 파울을 주고 경기장에서 내보낸 뒤, 같은 점수이거나 더 높은 점수의 A5로 교체해 40초 페널티를 수행하게 했다. 옳은가?', 0,
  '케이스북 12.104.1의 답: 옳다. A1은 경기장을 떠나야 하고 A5가 40초를 수행한다.', [104], ox=0)
c('12.104.2', 'A2가 팀 벤치에서 소변 주머니를 비운 것을 레퍼리가 발견해 디스퀄리파잉 파울을 주었다. 적절한 절차였는가?', 0,
  '케이스북 12.104.2의 답: 옳다.', [104], ox=0)
c('12.104.3', 'A팀의 3.0 선수가 디스쿄리파잉 파울을 받았다. 코트 위 선수는 2.0, 2.0, 1.0이고 교체로 들어올 수 있는 선수는 3.5와 2.5뿐이다. 누구로 교체하는가?', 0,
  '케이스북 12.104.3의 답: 점수 차가 같다면 높은 점수 선수를 넣는 것이 원칙이지만, 3.5를 넣으면 A팀이 8.5점이 되어 불법 라인업이 된다. 적법한 팀을 꾸릴 수 있으므로 몰수로 가지 않고 2.5를 넣어 경기를 계속한다.',
  [104, 35], ch=['2.5를 넣고 경기를 계속한다', '3.5를 넣는다', '경기를 몰수한다'], cEn=['Substitute the 2.5 and continue', 'Substitute the 3.5', 'Forfeit the game'])
c('12.104.4', 'A2가 디스퀄리파잉 파울을 범한 뒤 40초 시계가 시작되지 않았던 것이 드러났다. 레퍼리가 그 시점으로 돌아가 디스쿄리파잉 파울을 없애고 A2가 경기에 남게 했다. 옳은가?', 1,
  '케이스북 12.104.4의 답: 옳지 않다. 오류 시점으로 돌아가 페널티 수행은 취소하지만, 디스쿄리파잉 파울을 받은 선수는 그대로 퇴장된다. 그 선수는 경기장을 떠나고 교체 선수가 들어온다.', [104, 42], ox=1)
c('12.104.5', '데드볼 상황에서 A1이 코트 위 다른 선수에게 물리적으로 위협하고, 그 선수 방향으로 테이프 롤을 던졌다. 레퍼리가 A1에게 디스쿄리파잉 파울을 준 것은 옳은가?', 0,
  '케이스북 12.104.5의 답: 옳다. 위협하려는 시도나 겁을 주려고 물건을 던지는 행위는 디스쿄리파잉 파울 사유다.', [104], ox=0)
c('12.104.6', 'B1이 1쿼터에 플래그런트 파울을 받았다. 3쿼터 초반 트라이 라인 근처에서 A1을 쳤지만 파울은 없었고, 레퍼리가 듣지 못한 말로 A1과 신경전을 벌였다. 레퍼리가 두 선수와 이야기했다. 3쿼터 후반 B1이 비신사적으로 A1을 트라이 라인에서 회전시켰다. 레퍼리가 B1에게 디스쿄리파잉 파울을 준 것은 옳은가?', 0,
  '케이스북 12.104.6의 답: 옳다. 위협적인 행위와 이어지는 여러 차례의 비신사적 접촉은 디스쿄리파잉 파울로 격상한다.', [104, 103], ox=0)
c('13.106.1', 'B1이 호각 전 접촉 파울을 받고 욕설로 항의해 테크니컬 파울이 추가되었다. 계속해서 휠체어로 레퍼리를 밀어 위협하자 레퍼리가 B1을 퇴장시켰다. B코치는 선수 한 명(같은 점수, 동점이면 더 높은 점수)을 골라 B1이 받은 페널티 전부(호각 전 접촉 30초, 테크니컬 파울 30초, 디스퀄리파잉 파울 40초)를 수행하게 해야 한다. 옳은가?', 0,
  '케이스북 13.106.1의 답: 옳다. B팀 코치가 선수를 골라 페널티를 수행하게 한다.', [104, 106], ox=0)
c('13.106.2', 'B3가 일반 파울 페널티를 수행하던 중 페널티 시계가 잘 보이지 않아 시간이 다 된 줄 알고 몇 초를 남기고 코트로 돌아왔다. 페널티 타임키퍼가 다음 데드볼 때 레퍼리에게 알렸다. B3에게 테크니컬 파울을 주어야 하는가?', 0,
  '케이스북 13.106.2의 답: 옳다. 선수가 심판의 허락 없이 코트로 돌아왔다.', [106, 99], ox=0)
c('13.106.3', 'B2가 페널티를 수행하던 중 A3가 트라이를 성공했다. B2가 아무 허락 없이 페널티 박스에서 나와 코트로 들어왔다. 레퍼리가 불법 입장으로 B2에게 테크니컬 파울을 준 것은 옳은가?', 1,
  '케이스북 13.106.3의 답: 옳지 않다. 트라이가 성공하면 페널티를 수행하던 선수는 코트로 돌아올 수 있다. 다만 페널티 트라이 뒤에는 돌아올 수 없다.', [106, 88], ox=1)
c('13.106.4', 'B2가 페널티를 수행하던 중 상대에게 페널티 트라이가 주어졌고, 페널티 타임키퍼가 B2를 풀어주었다. 레퍼리가 불법 입장으로 B2에게 테크니컬 파울을 준 것은 옳은가?', 1,
  '케이스북 13.106.4의 답: 옳지 않다. 페널티 타임키퍼가 잘못 풀어준 것이다. B2는 추가 제재 없이 페널티 박스로 돌아가 남은 시간을 수행한다.', [106], ox=1)
c('13.106.5', '경기시계 4:40에 B1이 플래그런트 파울을 받았고, 처음 파울이 페널티 트라이여서 B1은 트라이 릴리즈 페널티 두 개를 수행해야 한다. 4:30에 B2가 일리걸 유스 오브 더 핸즈로 페널티를 받았다. 4:20에 A1이 트라이를 성공해 B1의 첫 페널티가 끝나고 두 번째가 4:20부터 시작되었다. 4:10에 A1이 다시 득점해, 페널티를 먼저 시작한 B2가 풀려났다. B1의 두 번째 페널티는 (4:10이 아니라) 4:20부터 계산해야 하는가?', 0,
  '케이스북 13.106.5의 답: 그렇다. 4:20이 맞다. 페널티 박스에 있는 선수의 위치 관리는 페널티 타임키퍼의 일차 책임이고, 레퍼리는 풀려나는 순서를 알고 지원해야 한다.', [106], ox=0)
c('13.106.6', '7:50에 B1이 파울로 페널티 박스에 들어갔고 7:25에 B2가 들어갔다. B1이 풀려나기 전에 B3가 파울을 받아 페널티 박스 뒤에서 기다렸다. B팀은 B5를 투입해 적법한 인원을 맞췄다. 7:20에 B1이 라이브 플레이 중 풀려났고, 페널티 타임키퍼가 경기 중단 전까지 B3가 페널티 박스에 들어가지 못하게 했다. 다음 중단 때 B팀이 교체해 적법한 라인업을 만들고 B3가 그때부터 페널티를 수행하기 시작했다. 옳은 절차인가?', 0,
  '케이스북 13.106.6의 답: 옳다.', [106, 70], ox=0)
